NAME_POOLS = {country: NAME_GROUPS[group] for country, group in COUNTRY_GROUPS.items()}

JOBS = ('演員', '歌手', '舞者', '偶像', '模特兒', '配音員', '主持人', '網紅', '導演', '編劇', '電影製作人', '電視製作人', '攝影師', '編舞師', '音樂製作人', '作曲家', '作詞人', '經紀人', '造型師', '服裝設計師', '化妝師', '藝術指導', '舞台設計師', '剪輯師', '廣告導演', '廣播主持人', '劇場演員', '舞台劇導演', '舞台監督', '特技演員')

def seed_into_connection(db, guild_id: int | str) -> dict[str, int]:
    """依國籍寫入素材；使用 INSERT OR IGNORE 保留群主新增的資料。"""
    guild_id = str(guild_id)
    names_added = jobs_added = 0
    for nationality, (surnames, given_names) in NAME_POOLS.items():
        for kind, values in (('surname', surnames), ('given', given_names)):
            for item in values.split():
                names_added += db.execute(
                    'INSERT OR IGNORE INTO extra_name_pool(guild_id,nationality,kind,value) VALUES(?,?,?,?)',
                    (guild_id, nationality, kind, item)
                ).rowcount
    for job in JOBS:
        jobs_added += db.execute(
            'INSERT OR IGNORE INTO extra_jobs(guild_id,job) VALUES(?,?)',
            (guild_id, job)
        ).rowcount
    return {'nationalities': len(NAME_POOLS), 'names_added': names_added, 'jobs_added': jobs_added}
